{
  "conversations": [
    {
      "title": "Ask for a specific place",
      "lines": [
        { "speaker": "you", "text": "Excuse me, where is the metro station?" },
        { "speaker": "you", "text": "Excuse me, where is the bus stop?", "or": true },
        { "speaker": "partner", "text": "It's just down this street." },
        { "speaker": "partner", "text": "It's around the corner.", "or": true },
        { "speaker": "you", "text": "Thank you." }
      ]
    },
    {
      "title": "Understand basic directions",
      "lines": [
        { "speaker": "partner", "text": "Go straight." },
        { "speaker": "partner", "text": "Turn left here.", "or": true },
        { "speaker": "partner", "text": "Turn right at the light.", "or": true },
        { "speaker": "you", "text": "Is it far?" },
        { "speaker": "partner", "text": "No, it's very close." },
        { "speaker": "partner", "text": "Yes, it's a ten minute walk.", "or": true },
        { "speaker": "you", "text": "Thanks a lot." }
      ]
    },
    {
      "title": "Ask to repeat or slow down",
      "lines": [
        { "speaker": "partner", "text": "Take the number twenty-two tram." },
        { "speaker": "you", "text": "Could you speak slower, please?" },
        { "speaker": "partner", "text": "Sure. Take the number twenty-two tram." },
        { "speaker": "you", "text": "Could you repeat that, please?" },
        { "speaker": "partner", "text": "Get off at the next stop." },
        { "speaker": "you", "text": "Got it, thank you." }
      ]
    }
  ]
}
